import { Deferred } from "./defer.js";
export type On<P extends any[] = []> = (fn: Fn<P>) => () => void;
export type Publish<P extends any[] = []> = (...p: P) => void;
export type Subby<P extends any[] = []> = On<P> & ReturnType<typeof mk<P>>;
export type Pubby<P extends any[] = []> = Publish<P> & ReturnType<typeof mk<P>>;
export declare function subby<P extends any[] = []>(fn?: Fn<P>): Subby<P>;
export declare function pubby<P extends any[] = []>(fn?: Fn<P>): Pubby<P>;
type Fn<P extends any[]> = (...p: P) => unknown;
declare function mk<P extends any[]>(): {
    set: Set<Fn<P>>;
    on: (fn: Fn<P>) => () => void;
    publish: (...p: P) => void;
    publishAsync: (...p: P) => Promise<void>;
    next: () => Deferred<P>;
    dispose: () => void;
};
export {};
